      {
        area: 'single vs multiple',
        level: 'flexible',
        note: 'type prop is free to choose based on whether sections are exclusive',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Borders, surfaces, and radii must resolve to --cascivo-* semantic tokens',
      },
    ],
  },
}
